{
  "identity": {
    "name": "Boise Remodeling Co. (DBA of P5 Home Co LLC)",
    "location": "4031 W Wapoot St, Meridian, ID 83646",
    "claims": [
      {
        "statement": "Boise Remodeling Co operates as a DBA of P5 Home Co LLC.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Boise Remodeling Co is a DBA of P5 Home Co LLC"
      },
      {
        "statement": "The business lists its address at 4031 W Wapoot St, Meridian, ID 83646 and operates as a service-area business rather than a staffed storefront.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/contact",
        "quote": "4031 W Wapoot St, Meridian, ID 83646 · Service-area business, not a staffed storefront"
      },
      {
        "statement": "The company serves homeowners across Ada and Canyon County in the Treasure Valley of Idaho, including Boise, Meridian, Eagle, Nampa, Kuna, Star, Middleton, and Caldwell.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/about",
        "quote": "We serve homeowners in Boise, Meridian, Eagle, Nampa, Kuna, Star, Middleton, Caldwell, and surrounding communities."
      },
      {
        "statement": "Boise Remodeling Co is part of P5 Home Co alongside affiliated brands Boise Construction Co, Boise Handyman Co, Boise Cabinet Co, and Boise ADU Co.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Part of P5 Home Co: Boise Construction Co · Boise Remodeling Co · Boise Handyman Co · Boise Cabinet Co · Boise ADU Co"
      }
    ]
  },
  "industry": {
    "industry": "Residential Design-Build Remodeling and General Contracting",
    "activities": [
      "Kitchen remodeling",
      "Bathroom remodeling",
      "Whole-home remodeling",
      "Room additions",
      "Accessory dwelling units (ADU / guest houses)",
      "Basement remodeling",
      "Outdoor living and decks",
      "Aging-in-place remodeling",
      "Design, estimating, and in-house Ada and Canyon County permitting"
    ],
    "claims": [
      {
        "statement": "Boise Remodeling Co is a design-build remodeling contractor handling kitchens, bathrooms, additions, and whole-home renovations across Ada and Canyon County.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Boise Remodeling Co is a design-build team for kitchens, bathrooms, additions, and whole-home work across Ada and Canyon County."
      },
      {
        "statement": "The company manages design, estimating, permitting, and construction under a single contract.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/services",
        "quote": "One accountable team handles design, estimating, permitting and construction under a single contract, from the first in-home visit through the final walkthrough."
      },
      {
        "statement": "Boise Remodeling Co does not operate as an HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://boiseremodeling.co/services",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://boiseremodeling.co/",
    "claims": [
      {
        "statement": "The company's business hours for calls and text replies are Monday through Friday 9 am to 6 pm and Saturday 9 am to 4 pm Mountain Time.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/contact",
        "quote": "Mon – Fri 9 am – 6 pm · Sat 9 am – 4 pm MT"
      },
      {
        "statement": "The company offers a free 60 to 90 minute in-home consultation and states it responds within one business day.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/contact",
        "quote": "Send a few details and we will reach out within one business day to schedule your free 60 to 90 minute in-home visit"
      },
      {
        "statement": "Published starting planning figures on the services page include Bathroom Remodel from $10k, Kitchen Remodel from $15k, Aging-in-Place from $20k, Outdoor Living from $25k, Basement from $35k, Whole-Home from $40k, Room Addition from $95k, and ADU from $165k.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/services",
        "quote": "Kitchen Remodel Custom kitchen renovations from cabinet refreshes to full gut-and-rebuild. Planning from $15k"
      },
      {
        "statement": "The company states that it operates lean without big offices, showrooms, or fleets of trucks, and reserves the right to subcontract services.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/about",
        "quote": "Big offices, showrooms, and fleets of trucks do not disappear. They get built into your price. We run lean on purpose"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Boise Remodeling Co lists Idaho Registered Contractor number 8381215 and states it is bonded and insured for residential remodeling work.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/about",
        "quote": "Idaho Registered Contractor #8381215 . We are bonded and insured for residential remodeling work across the Treasure Valley."
      },
      {
        "statement": "Pages on the website reference the Idaho Division of Occupational and Professional Licenses domains dopl.idaho.gov and edopl.idaho.gov.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "dopl.idaho.gov"
      }
    ],
    "limitations": "ForgeX can only read pages on the company's own website (boiseremodeling.co) and cannot independently query the external state licensing databases (dopl.idaho.gov or edopl.idaho.gov) to verify registration status, active dates, or standing."
  },
  "existingSoftware": [
    {
      "product": "Google Analytics 4 (GA4) and Google Ads",
      "purpose": "Website analytics, call/text tap tracking, Google forwarding numbers, and paid search lead attribution with deduplicated reference numbers",
      "evidence": {
        "statement": "The privacy policy states the company uses Google Analytics 4 (GA4) and Google Ads to measure visits, quote requests, calls, and texts.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "We use Google Analytics 4 (GA4) to understand how visitors use this site and Google Ads to measure which of our ads lead to quote"
      }
    },
    {
      "product": "Microsoft Clarity",
      "purpose": "Website behavior analytics via heatmaps and session recordings with masked form fields",
      "evidence": {
        "statement": "The privacy policy states the site uses Microsoft Clarity for heatmaps and session recordings.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "We also use Microsoft Clarity to see how visitors use our pages through heatmaps and session recordings; form fields are masked"
      }
    },
    {
      "product": "Meta Pixel and Meta Conversions API",
      "purpose": "Client-side and server-side conversion tracking for Facebook and Instagram advertising leads",
      "evidence": {
        "statement": "The privacy policy states the site uses the Meta Pixel and Meta's Conversions API to measure visits and inquiries from Facebook and Instagram ads.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "We also use the Meta Pixel and Meta's Conversions API to measure visits and inquiries from our Facebook and Instagram ads."
      }
    },
    {
      "product": "Online Remodel Cost Estimator & Automated Plan-Set Estimator",
      "purpose": "Interactive online project range estimator and automated construction drawing reader that extracts room areas, heights, and schedules from uploaded floor plans",
      "evidence": {
        "statement": "The website includes an automated plan-reading tool that extracts measurements from uploaded floor plans alongside human review by the estimating team.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/remodel-plans-boise",
        "quote": "They are stored with your enquiry and sent to our estimating team so we can review them by hand alongside the automatic read."
      }
    },
    {
      "product": "Subcontractor Portal",
      "purpose": "Web portal for subcontractors hosted on the company website",
      "evidence": {
        "statement": "The website includes a dedicated Subcontractor Portal route at /subcontractor.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/subcontractor",
        "quote": "Subcontractor Portal | Boise Remodeling Co"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company runs paid search and social advertising across Google Ads, Facebook, and Instagram to generate remodeling quote requests, calls, and texts.",
      "label": "fact",
      "sourceUrl": "https://boiseremodeling.co/privacy-policy",
      "quote": "We use Google Analytics 4 (GA4) to understand how visitors use this site and Google Ads to measure which of our ads lead to quote"
    },
    {
      "statement": "The company commits to sending weekly written project updates every Friday to remodeling clients.",
      "label": "fact",
      "sourceUrl": "https://boiseremodeling.co/about",
      "quote": "Instead of wondering what happened on your project this week, you receive a written update every Friday: what was completed, what is next"
    },
    {
      "statement": "The company already operates custom web intake tools, including an interactive cost estimator, a guided optional intake, and an automated floor-plan reader, as well as server-side ad event tracking.",
      "label": "inference",
      "sourceUrl": "https://boiseremodeling.co/remodel-plans-boise",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "No confirmed operational or lead-handling problem is observable on the public website.",
      "label": "inference",
      "basis": "Based on https://boiseremodeling.co/, https://boiseremodeling.co/privacy-policy, and https://boiseremodeling.co/remodel-plans-boise, the company already replies to texts in minutes during business hours, tracks ad leads via server-side Conversions API and deduplicated reference IDs, and provides automated online estimating and plan-reading tools."
    },
    {
      "problem": "Preparing weekly Friday written updates and reviewing uploaded floor plans by hand alongside the automatic read could require recurring project manager and estimator time.",
      "label": "hypothesis",
      "basis": "Plausible operational workload given the company's promises of weekly Friday written progress updates and manual estimator verification of uploaded plans, though there is no evidence that this causes a bottleneck."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Existing custom web application (online cost estimator, automated floor-plan reader, subcontractor portal, and server-side ad conversion tracking)",
      "addresses": "Lead capture, preliminary project range estimation, plan takeoff intake, and ad attribution",
      "alreadyOwned": true
    },
    {
      "solution": "Construction project management platforms (such as residential design-build management software)",
      "addresses": "Client portals, written change orders, subcontractor scheduling, and weekly progress logs",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Boise Remodeling Co. is a residential design-build general contractor outside ForgeX's target segment of HVAC, plumbing, and electrical service contractors, and already operates sophisticated custom web intake and estimating automation."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended. Notably, the company already uses an automated drawing reader with human-in-the-loop estimator verification on its own website."
  },
  "humanReview": [
    "No ForgeX automation is recommended; in the company's existing operations, human estimators review automated floor-plan reads and project managers issue written scopes and change orders."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Selling standardized home-service trade automations (built for high-volume HVAC, plumbing, and electrical dispatch) to a long-cycle design-build remodeling contractor risks poor workflow fit."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "Although the website publishes starting planning ranges on https://boiseremodeling.co/services (such as Bathroom Remodel 'Planning from $10k' and Kitchen Remodel 'Planning from $15k'), no ForgeX solution is recommended because the company is outside ForgeX's segment and has no evidenced automation gap.",
      "Therefore, no commercial value or implementation cost projection is claimed."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Managing Member (P5 Home Co LLC)",
      "General Manager",
      "Estimating / Operations Lead"
    ],
    "people": [],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://boiseremodeling.co/contact"
      }
    ]
  },
  "discovery": {
    "questions": [
      "What back-office construction management or CRM system does P5 Home Co use behind your custom website and subcontractor portal?",
      "How many full-time staff versus subcontractors work across the P5 Home Co brands?",
      "Are there any manual handoffs between your online estimator/plan reader and your project management workflow?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://boiseremodeling.co/",
        "usedFor": "Business identity, DBA and parent entity (P5 Home Co LLC), contractor registration number, service overview, and contact details"
      },
      {
        "url": "https://boiseremodeling.co/about",
        "usedFor": "Design-build operating model, lean overhead structure, service areas, licensing/bonding statement, and weekly Friday update commitment"
      },
      {
        "url": "https://boiseremodeling.co/contact",
        "usedFor": "Meridian physical address, business hours, response time commitments, and primary business contact channel"
      },
      {
        "url": "https://boiseremodeling.co/subcontractor",
        "usedFor": "Verification of the on-site Subcontractor Portal route"
      },
      {
        "url": "https://boiseremodeling.co/services",
        "usedFor": "Principal remodeling activities and published starting planning ranges"
      },
      {
        "url": "https://boiseremodeling.co/privacy-policy",
        "usedFor": "Verification of Google Analytics 4, Google Ads, Microsoft Clarity, Meta Pixel, and Meta Conversions API usage"
      },
      {
        "url": "https://boiseremodeling.co/estimate",
        "usedFor": "Verification of the online Remodel Cost Estimator tool"
      },
      {
        "url": "https://boiseremodeling.co/terms-of-service",
        "usedFor": "Payment terms, subcontracting policy, and service terms"
      },
      {
        "url": "https://boiseremodeling.co/remodel-plans-boise",
        "usedFor": "Verification of the automated floor-plan reader and human-in-the-loop estimator review process"
      }
    ],
    "limitations": [
      "The website does not disclose total employee headcount (whether the company has 10 to 75 staff) and notes that it runs lean and subcontracts services as needed.",
      "The website footer lists an individual under the title 'Public representative' rather than explicitly presenting them as an owner, executive, or manager; per ForgeX evidence rules, they are omitted from the named people list.",
      "Internal back-office software (such as accounting or construction project management software behind the custom web app) cannot be verified from public pages.",
      "State contractor registration status on dopl.idaho.gov / edopl.idaho.gov cannot be independently queried by ForgeX's site-restricted fetcher."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Boise Remodeling Co. (a DBA of P5 Home Co LLC) is a residential design-build general remodeling contractor specializing in kitchens, bathrooms, additions, whole-home renovations, and ADUs, which puts it outside ForgeX's target segment of HVAC, plumbing, and electrical service contractors with 10 to 75 staff. Furthermore, the company already operates a modern custom web stack featuring an interactive cost estimator, an automated floor-plan measurement reader with human review, a subcontractor portal, fast text response during business hours, and server-side ad conversion tracking (Meta Conversions API and Google Ads)."
  }
}
